style.css:
@-moz-document domain("bandlab.com") {
/* General body and background */
  body, .sc-eCImPb, .sc-hmdomO {
    background-color: #fffbe6 !important; /* fluffy pastel yellow */
    color: #5a4a2a !important; /* warm retro brown text */
  }

  /* Make all text retro brown */
  * {
    color: #5a4a2a !important;
    background-color: transparent !important;
    box-shadow: none !important;
  }

  /* Outlines for buttons */
  button, .sc-eDvSVe, .sc-dxgOiQ, .sc-jSMfEi, .sc-kLgntA {
    border: 1px solid #e6c34d !important; /* golden border */
    background-color: #ffe680 !important; /* creamy retro yellow */
    color: #3a2f1a !important;
    border-radius: 6px !important;
  }

  /* Inputs and dropdowns */
  input, select, textarea {
    background-color: #fff9cc !important; /* pale cream */
    color: #3a2f1a !important;
    border: 1px solid #e6c34d !important;
  }

  /* Remove background images or shadows */
  [style*="background-image"], [class*="background"] {
    background: none !important;
  }

  /* Sliders, knobs, etc. */
  .sc-hGoxap, .sc-hlTVkV {
    background-color: #ffe680 !important;
    border: 1px solid #e6c34d !important;
  }

  /* Hover effects */
  button:hover, .sc-dxgOiQ:hover {
    background-color: #ffd633 !important; /* brighter retro yellow */
    color: #3a2f1a !important;
    border-color: #e6c34d !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
  }
  ::-webkit-scrollbar-track {
    background: #fffbe6;
  }
  ::-webkit-scrollbar-thumb {
    background: #e6c34d;
    border-radius: 4px;
  }

  /* Logos / icons retro tint */
  img, svg, .logo, .sc-jIAOiI {
    filter: sepia(60%) saturate(120%) brightness(110%) !important;
  }
}
